bool XmlNameValuePair::getValue(double& value) const
{
	if (valueType == DOUBLE)
	{
		value = doubleValue;
		return true;
	}
	if (valueType == FLOAT)
	{
		value = floatValue;
		clearValue();
		doubleValue = value;
		valueType = DOUBLE;
		return true;
	}
	else if (valueType == STRING)
	{
		if (!RBX::StringConverter<double>::convertToValue(*stringValue, value))
			return false;
	}
	else
		return false;
	clearValue();
	doubleValue = value;
	valueType = DOUBLE;
	return true;
}

